"use client";

import React, { useState, createContext, useContext } from "react";
import { motion, AnimatePresence, type Transition } from "motion/react";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { cn } from "@/lib/utils";

interface CarouselContextValue {
  currentPage: number;
  totalPages: number;
  nextPage: () => void;
  prevPage: () => void;
  gotoPage: (page: number) => void;
}

const CarouselContext = createContext<CarouselContextValue | null>(null);

export function useCarousel() {
  const ctx = useContext(CarouselContext);
  if (!ctx) {
    throw new Error("useCarousel must be used within <MotionCarousel />");
  }
  return ctx;
}

export interface CarouselSlide {
  id: string;
  title: string;
  subtitle: string;
  image: string;
}

const DEFAULT_SLIDES: CarouselSlide[] = [
  {
    id: "1",
    title: "Cinematic Atmosphere",
    subtitle: "High-resolution architectural renders",
    image: "https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80",
  },
  {
    id: "2",
    title: "Ethereal Landscapes",
    subtitle: "Deep forest volumetric lighting",
    image: "https://images.unsplash.com/photo-1511497584788-87676104235f?auto=format&fit=crop&w=800&q=80",
  },
  {
    id: "3",
    title: "Alpine Peaks",
    subtitle: "Glacial trails and mountain passes",
    image: "https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80",
  },
];

const springTransition: Transition = {
  type: "spring",
  stiffness: 350,
  damping: 30,
};

export function MotionCarousel({
  slides = DEFAULT_SLIDES,
  className,
}: {
  slides?: CarouselSlide[];
  className?: string;
}) {
  const [currentPage, setCurrentPage] = useState(0);
  const [direction, setDirection] = useState(0);

  const totalPages = slides.length;

  const nextPage = () => {
    setDirection(1);
    setCurrentPage((prev) => (prev + 1) % totalPages);
  };

  const prevPage = () => {
    setDirection(-1);
    setCurrentPage((prev) => (prev - 1 + totalPages) % totalPages);
  };

  const gotoPage = (page: number) => {
    setDirection(page > currentPage ? 1 : -1);
    setCurrentPage(page);
  };

  const activeSlide = slides[currentPage];

  const carouselVariants = {
    enter: (d: number) => ({
      opacity: 0,
      x: d * 300,
      scale: 0.95,
    }),
    center: {
      opacity: 1,
      x: 0,
      scale: 1,
    },
    exit: (d: number) => ({
      opacity: 0,
      x: -d * 300,
      scale: 0.95,
    }),
  };

  return (
    <CarouselContext.Provider
      value={{
        currentPage,
        totalPages,
        nextPage,
        prevPage,
        gotoPage,
      }}
    >
      <div
        data-slot="motion-carousel"
        className={cn(
          "relative flex flex-col items-center w-full max-w-xl mx-auto select-none gap-4",
          className
        )}
      >
        {/* Viewport Frame */}
        <div className="relative w-full h-80 overflow-hidden rounded-3xl border border-neutral-200 dark:border-neutral-800 bg-neutral-950 shadow-2xl">
          <AnimatePresence initial={false} custom={direction} mode="popLayout">
            <motion.div
              key={activeSlide.id}
              custom={direction}
              variants={carouselVariants}
              initial="enter"
              animate="center"
              exit="exit"
              transition={springTransition}
              className="absolute inset-0 h-full w-full"
            >
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={activeSlide.image}
                alt={activeSlide.title}
                className="h-full w-full object-cover"
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent" />

              <div className="absolute bottom-6 left-6 right-6 text-white">
                <span className="text-[10px] font-mono font-bold uppercase tracking-wider text-pink-400">
                  Slide {currentPage + 1} of {totalPages}
                </span>
                <h3 className="text-xl font-bold tracking-tight mt-0.5">
                  {activeSlide.title}
                </h3>
                <p className="text-xs text-white/80 mt-1">
                  {activeSlide.subtitle}
                </p>
              </div>
            </motion.div>
          </AnimatePresence>

          {/* Navigation Overlay Buttons */}
          <button
            type="button"
            onClick={prevPage}
            aria-label="Previous Slide"
            className="absolute top-1/2 left-4 -translate-y-1/2 z-20 flex h-9 w-9 items-center justify-center rounded-full bg-black/40 text-white backdrop-blur-md transition-transform hover:scale-110 active:scale-95 cursor-pointer"
          >
            <ChevronLeft className="h-4 w-4" />
          </button>

          <button
            type="button"
            onClick={nextPage}
            aria-label="Next Slide"
            className="absolute top-1/2 right-4 -translate-y-1/2 z-20 flex h-9 w-9 items-center justify-center rounded-full bg-black/40 text-white backdrop-blur-md transition-transform hover:scale-110 active:scale-95 cursor-pointer"
          >
            <ChevronRight className="h-4 w-4" />
          </button>
        </div>

        {/* Headless Dots Pagination */}
        <div className="flex items-center gap-2">
          {Array.from({ length: totalPages }).map((_, index) => (
            <motion.button
              key={index}
              type="button"
              onClick={() => gotoPage(index)}
              animate={{
                scale: currentPage === index ? 1.25 : 1,
                opacity: currentPage === index ? 1 : 0.4,
              }}
              className={cn(
                "h-2 rounded-full transition-all cursor-pointer",
                currentPage === index ? "w-6 bg-pink-500" : "w-2 bg-neutral-400"
              )}
            />
          ))}
        </div>
      </div>
    </CarouselContext.Provider>
  );
}
